SELECT 
    (SELECT AVG(Consumption) FROM yearmonth WHERE CustomerID IN (
        SELECT CustomerID FROM yearmonth WHERE Date BETWEEN '201301' AND '201312' AND CustomerID IN (
            SELECT CustomerID FROM customers WHERE Currency = 'CZK' AND Segment = 'SME'
        ) ORDER BY Consumption ASC LIMIT 1
    ) AND Date BETWEEN '201301' AND '201312') AS SME_Annual_Average,
    (SELECT AVG(Consumption) FROM yearmonth WHERE CustomerID IN (
        SELECT CustomerID FROM yearmonth WHERE Date BETWEEN '201301' AND '201312' AND CustomerID IN (
            SELECT CustomerID FROM customers WHERE Currency = 'CZK' AND Segment = 'LAM'
        ) ORDER BY Consumption ASC LIMIT 1
    ) AND Date BETWEEN '201301' AND '201312') AS LAM_Annual_Average,
    (SELECT AVG(Consumption) FROM yearmonth WHERE CustomerID IN (
        SELECT CustomerID FROM yearmonth WHERE Date BETWEEN '201301' AND '201312' AND CustomerID IN (
            SELECT CustomerID FROM customers WHERE Currency = 'CZK' AND Segment = 'KAM'
        ) ORDER BY Consumption ASC LIMIT 1
    ) AND Date BETWEEN '201301' AND '201312') AS KAM_Annual_Average

